#!/usr/bin/env node
// Differential harness: runs the reference executable (and optionally our JS impl)
// over a list of markdown inputs, comparing outputs.
import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const EXE = '/workspace/dataset/test11_executable';
const MINE = '/output/test11.mjs';

const casesFile = process.argv[2] || '/tmp/probe/cases.json';
const mode = process.argv[3] || 'both'; // ref | both
const filter = process.argv[4] || null;

const cases = JSON.parse(readFileSync(casesFile, 'utf8'));

function runExe(t) {
  const r = spawnSync(EXE, [`--a=${t}`, `--b=${t}`, `--c=${t}`], { encoding: 'utf8', maxBuffer: 1 << 26 });
  return { out: r.stdout ?? '', err: r.stderr ?? '', rc: r.status };
}
function runMine(t) {
  const r = spawnSync('node', [MINE, `--a=${t}`, `--b=${t}`, `--c=${t}`], { encoding: 'utf8', maxBuffer: 1 << 26 });
  return { out: r.stdout ?? '', err: r.stderr ?? '', rc: r.status };
}

const vis = (s) => JSON.stringify(s);

let pass = 0, fail = 0;
const failures = [];
const cacheFile = casesFile + '.ref.json';
let cache = existsSync(cacheFile) ? JSON.parse(readFileSync(cacheFile, 'utf8')) : {};

for (let i = 0; i < cases.length; i++) {
  const c = cases[i];
  const label = typeof c === 'object' ? c.name : `case${i}`;
  const text = typeof c === 'object' ? c.text : c;
  if (filter && !label.includes(filter)) continue;
  let ref = cache[text];
  if (!ref) { ref = runExe(text); cache[text] = ref; }
  if (mode === 'ref') {
    console.log(`--- ${label} :: ${vis(text)}`);
    console.log(ref.out.replace(/\n$/, '').split('\n').map(l => '  | ' + l).join('\n'));
    if (ref.rc !== 0) console.log('  RC=' + ref.rc + ' ERR=' + ref.err);
    continue;
  }
  const got = runMine(text);
  if (got.out === ref.out && got.rc === ref.rc) { pass++; }
  else {
    fail++;
    failures.push({ label, text, ref, got });
  }
}
writeFileSync(cacheFile, JSON.stringify(cache, null, 1));

if (mode !== 'ref') {
  for (const f of failures) {
    console.log('='.repeat(70));
    console.log(`FAIL ${f.label} :: ${vis(f.text)}`);
    console.log('--- expected (rc=' + f.ref.rc + ')');
    console.log(f.ref.out.split('\n').map(l => '  E| ' + l).join('\n'));
    console.log('--- got (rc=' + f.got.rc + ')');
    console.log(f.got.out.split('\n').map(l => '  G| ' + l).join('\n'));
    if (f.got.err) console.log('  STDERR: ' + f.got.err.split('\n').slice(0, 8).join('\n    '));
  }
  console.log('='.repeat(70));
  console.log(`PASS ${pass}  FAIL ${fail}`);
}

