// OFFLINE build-time generator (not shipped): emits compact range data for
// Python's unicode-aware \w  ==  [\p{L}\p{N}_]
const test = (cp) => {
  const s = String.fromCodePoint(cp);
  return /[\p{L}\p{N}_]/u.test(s);
};
const ranges = [];
let start = -1;
for (let cp = 0; cp <= 0x10FFFF; cp++) {
  if (cp >= 0xD800 && cp <= 0xDFFF) { if (start >= 0) { ranges.push([start, cp - 1]); start = -1; } continue; }
  const ok = test(cp);
  if (ok && start < 0) start = cp;
  else if (!ok && start >= 0) { ranges.push([start, cp - 1]); start = -1; }
}
if (start >= 0) ranges.push([start, 0x10FFFF]);
// delta-encode: gap from previous end, then length-1
let prev = 0; const parts = [];
for (const [a, b] of ranges) { parts.push((a - prev).toString(36) + '.' + (b - a).toString(36)); prev = b; }
const data = parts.join(',');
console.log('ranges:', ranges.length, 'chars:', data.length);
process.stdout.write('');
import { writeFileSync } from 'node:fs';
writeFileSync('/tmp/probe/worddata.txt', data);
EOF
