cd /tmp/probe && node -e '
const {readFileSync, writeFileSync} = require("fs");
const data = readFileSync("/tmp/probe/worddata.txt","utf8");
const chunks = [];
for (let i=0;i<data.length;i+=96) chunks.push("  " + JSON.stringify(data.slice(i,i+96)));
const out = `/**
 * Compact Unicode range table for Python\x27s unicode-aware \\\\w character class,
 * i.e. the set [\\\\p{L}\\\\p{N}_].  Python decides word-ness with
 * Py_UNICODE_ISALNUM(ch) || ch == \x27_\x27, which is equivalent to the union of the
 * Unicode Letter and Number general categories plus U+005F.
 *
 * The table is stored as a delta-encoded, base-36 string so that the runtime
 * needs no pattern-matching machinery to reconstruct it: each entry is
 * "<gap>.<span>" where <gap> is the distance from the previous range end to this
 * range start and <span> is the range length minus one.
 */

const PACKED = [
${chunks.join(" +\n")}
].join("");

function unpack(packed) {
  const starts = [];
  const ends = [];
  let prev = 0;
  let i = 0;
  const len = packed.length;
  while (i < len) {
    let dot = packed.indexOf(".", i);
    const gap = parseInt(packed.slice(i, dot), 36);
    let comma = packed.indexOf(",", dot);
    if (comma < 0) comma = len;
    const span = parseInt(packed.slice(dot + 1, comma), 36);
    const start = prev + gap;
    const end = start + span;
    starts.push(start);
    ends.push(end);
    prev = end;
    i = comma + 1;
  }
  return { starts, ends };
}

const { starts: START, ends: END } = unpack(PACKED);

/**
 * True when \x60codePoint\x60 belongs to Python\x27s \\\\w class. Binary search keeps the
 * lookup O(log n) which matters because emphasis matching probes it per char.
 */
export function isWordCodePoint(codePoint) {
  if (codePoint === undefined || codePoint === null || codePoint < 0) return false;
  let lo = 0;
  let hi = START.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (codePoint < START[mid]) hi = mid - 1;
    else if (codePoint > END[mid]) lo = mid + 1;
    else return true;
  }
  return false;
}
`;
writeFileSync("/output/lib/core/unicode-data.mjs", out);
