/**
 * Character classification and Python-flavoured string helpers.
 *
 * Everything in this project is matched by hand-written scanners, so this module
 * is the vocabulary the scanners are written in.  The semantics deliberately
 * mirror CPython's `str` methods and `re` character classes rather than
 * JavaScript's, because the output has to agree with Python-Markdown byte for
 * byte.
 */

import { isWordCodePoint } from './unicode-data.mjs';

/** Characters CPython's `str.strip()` removes when no argument is given. */
const PY_SPACE = new Set([
  '\t', '\n', '\v', '\f', '\r', ' ',
  '', '', '', '',
  '', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', '　',
]);

/** Matches `\s` in a Python regular expression over `str`. */
export function isSpace(ch) {
  return ch !== undefined && PY_SPACE.has(ch);
}

/** Matches `\w` in a Python regular expression over `str`. */
export function isWord(ch) {
  if (ch === undefined || ch === '') return false;
  return isWordCodePoint(ch.codePointAt(0));
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function isAsciiLetter(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

export function isAsciiAlnum(ch) {
  return isAsciiLetter(ch) || isDigit(ch);
}

/** `str.strip()` — both ends, Python's whitespace set. */
export function strip(s) {
  return lstrip(rstrip(s));
}

/** `str.lstrip()`, or `str.lstrip(chars)` when `chars` is given. */
export function lstrip(s, chars) {
  let i = 0;
  if (chars === undefined) {
    while (i < s.length && PY_SPACE.has(s[i])) i++;
  } else {
    while (i < s.length && chars.includes(s[i])) i++;
  }
  return s.slice(i);
}

/** `str.rstrip()`, or `str.rstrip(chars)` when `chars` is given. */
export function rstrip(s, chars) {
  let i = s.length;
  if (chars === undefined) {
    while (i > 0 && PY_SPACE.has(s[i - 1])) i--;
  } else {
    while (i > 0 && chars.includes(s[i - 1])) i--;
  }
  return s.slice(0, i);
}

/** `str.strip(chars)` with an explicit character set. */
export function stripChars(s, chars) {
  return lstrip(rstrip(s, chars), chars);
}

/** True when the string is empty or contains only whitespace. */
export function isBlank(s) {
  return strip(s) === '';
}

/**
 * `str.expandtabs(tabsize)`.  Column counting restarts at every newline, which
 * is what makes indented code blocks line up the way Python-Markdown expects.
 */
export function expandTabs(s, tabsize = 8) {
  let out = '';
  let col = 0;
  for (const ch of s) {
    if (ch === '\t') {
      const width = tabsize > 0 ? tabsize - (col % tabsize) : 0;
      out += ' '.repeat(width);
      col += width;
    } else {
      out += ch;
      if (ch === '\n' || ch === '\r') col = 0;
      else col += 1;
    }
  }
  return out;
}

/** Count how many of `ch` appear starting at `pos`. */
export function runLength(s, pos, ch) {
  let n = 0;
  while (pos + n < s.length && s[pos + n] === ch) n++;
  return n;
}

/** Count how many of `ch` appear immediately before `pos`. */
export function backRunLength(s, pos, ch) {
  let n = 0;
  while (pos - n - 1 >= 0 && s[pos - n - 1] === ch) n++;
  return n;
}

/** Index of the first character at or after `pos` that is not a space. */
export function skipSpaces(s, pos) {
  let i = pos;
  while (i < s.length && s[i] === ' ') i++;
  return i;
}

/** Number of leading spaces (tabs are expanded long before we get here). */
export function indentOf(line) {
  let n = 0;
  while (n < line.length && line[n] === ' ') n++;
  return n;
}

/** True when every character of `s` is in `allowed`. Mirrors `set(s) <= set(allowed)`. */
export function charsSubsetOf(s, allowed) {
  for (const ch of s) {
    if (!allowed.includes(ch)) return false;
  }
  return true;
}

/** `s.startswith(prefix, pos)`. */
export function startsWith(s, prefix, pos = 0) {
  if (pos + prefix.length > s.length) return false;
  for (let i = 0; i < prefix.length; i++) {
    if (s[pos + i] !== prefix[i]) return false;
  }
  return true;
}

