/**
 * A minimal stand-in for `xml.etree.ElementTree.Element`.
 *
 * Only the pieces Python-Markdown actually leans on are modelled: ordered
 * children, the `text`/`tail` split, and attribute assignment.  Attribute
 * *iteration* order is irrelevant because the serializer sorts keys, but
 * insertion order is preserved anyway so debugging output reads naturally.
 */

import { AtomicString, textOf } from './util.mjs';

/** Sentinel tag for an HTML comment node, mirroring `ElementTree.Comment`. */
export const COMMENT = Symbol('Comment');
/** Sentinel tag for a processing instruction. */
export const PROCESSING_INSTRUCTION = Symbol('ProcessingInstruction');

export class Element {
  constructor(tag, attrib = null) {
    this.tag = tag;
    this.attrib = new Map();
    this.text = null;
    this.tail = null;
    this.children = [];
    if (attrib) {
      for (const [key, value] of Object.entries(attrib)) this.set(key, value);
    }
  }

  set(key, value) {
    this.attrib.set(key, String(value));
  }

  get(key, fallback = null) {
    return this.attrib.has(key) ? this.attrib.get(key) : fallback;
  }

  has(key) {
    return this.attrib.has(key);
  }

  delete(key) {
    this.attrib.delete(key);
  }

  items() {
    return [...this.attrib.entries()];
  }

  /** Number of child elements — `len(elem)` in Python. */
  get length() {
    return this.children.length;
  }

  append(child) {
    this.children.push(child);
    return child;
  }

  extend(children) {
    for (const child of children) this.children.push(child);
  }

  insert(index, child) {
    this.children.splice(index, 0, child);
    return child;
  }

  remove(child) {
    const index = this.children.indexOf(child);
    if (index >= 0) this.children.splice(index, 1);
  }

  /** `elem[index]`, supporting Python's negative indexing. */
  child(index) {
    const i = index < 0 ? this.children.length + index : index;
    return this.children[i];
  }

  get last() {
    return this.children[this.children.length - 1];
  }

  /** `elem.text` with any `AtomicString` box removed. */
  get plainText() {
    return textOf(this.text);
  }

  get plainTail() {
    return textOf(this.tail);
  }

  /** Depth-first iteration over this element and its descendants. */
  *iter(tag = null) {
    if (tag === null || this.tag === tag) yield this;
    for (const child of this.children) {
      if (child instanceof Element) yield* child.iter(tag);
    }
  }

  /** Depth-first iteration yielding `[element, parent]` pairs. */
  *iterWithParents(parent = null) {
    yield [this, parent];
    for (const child of this.children) {
      if (child instanceof Element) yield* child.iterWithParents(this);
    }
  }
}

/** `ElementTree.SubElement(parent, tag, attrib)`. */
export function subElement(parent, tag, attrib = null) {
  const element = new Element(tag, attrib);
  parent.append(element);
  return element;
}

/** Wrap a value so downstream inline processing leaves it alone. */
export function atomic(value) {
  return new AtomicString(value);
}

