/**
 * Element tree to HTML/XHTML text.
 *
 * Ported from the serializer Python-Markdown carries in place of the stdlib one.
 * Two details are load-bearing for output equality:
 *
 *  1. attributes are emitted in sorted key order, not insertion order; and
 *  2. a bare `&` is only turned into `&amp;` when it does *not* already look
 *     like a character reference (see `looksLikeEntity`).
 */

import { COMMENT, Element, PROCESSING_INSTRUCTION } from './element.mjs';
import { looksLikeEntity, textOf } from './util.mjs';

/** Tags written as `<tag />` in XHTML and left unclosed in HTML. */
const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

/** Tags whose text content is emitted raw. */
const RAW_TEXT = new Set(['script', 'style']);

function escapeAmpersands(text) {
  if (!text.includes('&')) return text;
  let out = '';
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '&' && !looksLikeEntity(text, i)) out += '&amp;';
    else out += text[i];
  }
  return out;
}

/** `_escape_cdata` — character data outside of attributes. */
function escapeCdata(text) {
  let out = escapeAmpersands(text);
  if (out.includes('<')) out = out.split('<').join('&lt;');
  if (out.includes('>')) out = out.split('>').join('&gt;');
  return out;
}

/** `_escape_attrib_html` — note that `'` is deliberately left alone. */
function escapeAttrib(text) {
  let out = escapeAmpersands(text);
  if (out.includes('<')) out = out.split('<').join('&lt;');
  if (out.includes('>')) out = out.split('>').join('&gt;');
  if (out.includes('"')) out = out.split('"').join('&quot;');
  return out;
}

function serializeInto(parts, element, format) {
  const tag = element.tag;
  const text = textOf(element.text);

  if (tag === COMMENT) {
    parts.push('<!--' + (text ?? '') + '-->');
  } else if (tag === PROCESSING_INSTRUCTION) {
    parts.push('<?' + (text ?? '') + '?>');
  } else if (tag === null) {
    // A bare fragment: emit children only.
    if (text) parts.push(escapeCdata(text));
    for (const child of element.children) serializeInto(parts, child, format);
  } else {
    parts.push('<' + tag);
    const items = element.items();
    if (items.length) {
      items.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
      for (const [key, value] of items) {
        parts.push(' ' + key + '="' + escapeAttrib(value) + '"');
      }
    }
    const lower = typeof tag === 'string' ? tag.toLowerCase() : '';
    if (format === 'xhtml' && HTML_EMPTY.has(lower)) {
      parts.push(' />');
    } else {
      parts.push('>');
      if (text) parts.push(RAW_TEXT.has(lower) ? text : escapeCdata(text));
      for (const child of element.children) serializeInto(parts, child, format);
      if (!HTML_EMPTY.has(lower)) parts.push('</' + tag + '>');
    }
  }

  const tail = textOf(element.tail);
  if (tail) parts.push(escapeCdata(tail));
}

function serialize(element, format) {
  const parts = [];
  serializeInto(parts, element, format);
  return parts.join('');
}

export function toXhtmlString(element) {
  return serialize(element, 'xhtml');
}

