import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test11_executable';
const tags = ('a abbr address area article aside audio b base basefont bdi bdo big blockquote body br button ' +
  'canvas caption center cite code col colgroup data datalist dd del details dfn dialog dir div dl dt em embed ' +
  'fieldset figcaption figure font footer form frame frameset group h1 h2 h3 h4 h5 h6 head header hgroup hr html ' +
  'i iframe img input ins isindex kbd label legend li link main map mark math menu meta meter nav noframes noscript ' +
  'object ol optgroup option output p param picture pre progress q rp rt ruby s samp script section select small ' +
  'source span strike strong style sub summary sup svg table tbody td template textarea tfoot th thead time title ' +
  'tr track tt u ul var video wbr').split(/\s+/);

const blockish = [];
const emptyish = [];
for (const t of tags) {
  // Raw-block detection: a paired tag at line start becomes an unwrapped raw block.
  const paired = `<${t}>\nx\n</${t}>`;
  let r = spawnSync(EXE, [`--a=${paired}`, '--b=x', '--c=x'], { encoding: 'utf8' });
  const out = (r.stdout || '').split('\n')[0];
  const isBlock = !out.startsWith('<p>');
  if (isBlock) blockish.push(t);

  // empty_tags detection: a lone unpaired start tag that still ends the raw run.
  const lone = `<${t}>\n\nafter`;
  r = spawnSync(EXE, [`--a=${lone}`, '--b=x', '--c=x'], { encoding: 'utf8' });
  const lines = (r.stdout || '').split('\n');
  const sawAfter = lines.some((l) => l === '<p>after</p>');
  if (sawAfter && isBlock) emptyish.push(t);
}
console.log('BLOCK:', JSON.stringify(blockish));
console.log('EMPTY_TAGS(candidates):', JSON.stringify(emptyish));

