/**
 * Constants and small services shared by every stage of the pipeline.
 *
 * Python-Markdown threads content between stages by swapping fragments out for
 * sentinel placeholders built from the STX/ETX control characters.  Those exact
 * sentinels leak into observable behaviour (a stray STX in the input is
 * stripped, `<p>PLACEHOLDER</p>` is rewritten wholesale by the raw-HTML
 * postprocessor), so they are reproduced verbatim here.
 */

import { isAsciiAlnum, isAsciiLetter, isDigit, isHexDigit } from './chars.mjs';

export const STX = '\u0002';
export const ETX = '\u0003';

export const INLINE_PLACEHOLDER_PREFIX = STX + 'klzzwxh:';
export const INLINE_PLACEHOLDER_SUFFIX = ETX;
/** Width of `STX + "klzzwxh:" + %04d + ETX`. */
export const INLINE_PLACEHOLDER_LENGTH = INLINE_PLACEHOLDER_PREFIX.length + 4 + 1;

export const AMP_SUBSTITUTE = STX + 'amp' + ETX;
export const HTML_PLACEHOLDER_PREFIX = STX + 'wzxhzdk:';

export function inlinePlaceholder(index) {
  return INLINE_PLACEHOLDER_PREFIX + String(index).padStart(4, '0') + INLINE_PLACEHOLDER_SUFFIX;
}

export function htmlPlaceholder(index) {
  return HTML_PLACEHOLDER_PREFIX + String(index) + ETX;
}

/** Block-level tag names, as Python-Markdown classifies them. */
export const BLOCK_LEVEL_ELEMENTS = [
  'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl',
  'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3',
  'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol',
  'p', 'pre', 'section', 'table', 'ul',
  'dd', 'dt', 'frameset', 'li', 'tbody', 'td', 'tfoot', 'th', 'thead', 'tr',
  'iframe', 'video', 'audio', 'canvas', 'colgroup', 'summary', 'legend',
  'caption', 'col', 'optgroup', 'option', 'select', 'textarea', 'label',
  'noscript', 'output', 'progress', 'ruby', 'source', 'track',
  'center', 'dir', 'noframes',
];

/** Characters a backslash may escape. Extensions append to this list. */
export const DEFAULT_ESCAPED_CHARS = [
  '\\', '`', '*', '_', '{', '}', '[', ']', '(', ')', '>', '#', '+', '-', '.', '!',
];

/** `&`, `<` and `>` escaping used for the contents of a `<code>` element. */
export function codeEscape(text) {
  let out = text;
  if (out.includes('&')) out = out.split('&').join('&amp;');
  if (out.includes('<')) out = out.split('<').join('&lt;');
  if (out.includes('>')) out = out.split('>').join('&gt;');
  return out;
}

/**
 * Marker for text that must not be re-scanned for inline patterns. Python uses a
 * `str` subclass; JavaScript strings cannot be subclassed usefully, so atomic
 * strings are boxed and unwrapped at the edges.
 */
export class AtomicString {
  constructor(value) {
    this.value = String(value);
  }
  toString() {
    return this.value;
  }
}

export function isAtomic(value) {
  return value instanceof AtomicString;
}

/** Unwrap an `AtomicString` (or pass a plain string / null through). */
export function textOf(value) {
  if (value === null || value === undefined) return value;
  return value instanceof AtomicString ? value.value : value;
}

/**
 * Stash for raw HTML pulled out of the document before Markdown parsing. The
 * index a fragment lands on is part of the output contract because the
 * postprocessor walks the stash in order.
 */
export class HtmlStash {
  constructor() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
    this.tagData = [];
  }

  /** Store raw HTML and return the placeholder that stands in for it. */
  store(html) {
    this.rawHtmlBlocks.push(html);
    const placeholder = this.getPlaceholder(this.htmlCounter);
    this.htmlCounter += 1;
    return placeholder;
  }

  reset() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
  }

  getPlaceholder(index) {
    return htmlPlaceholder(index);
  }
}

/**
 * Ordered collection keyed by name and sorted by descending priority — the
 * mechanism Python-Markdown uses for pre/post/tree/block/inline processors.
 */
export class Registry {
  constructor() {
    this._data = new Map();
    this._priority = [];
    this._sorted = null;
  }

  register(item, name, priority) {
    if (this._data.has(name)) this.deregister(name, false);
    this._priority.push({ name, priority });
    this._data.set(name, item);
    this._sorted = null;
  }

  deregister(name, strict = true) {
    if (!this._data.has(name)) {
      if (strict) throw new Error(`No item named "${name}" exists.`);
      return;
    }
    this._data.delete(name);
    this._priority = this._priority.filter((entry) => entry.name !== name);
    this._sorted = null;
  }

  has(name) {
    return this._data.has(name);
  }

  get(name) {
    return this._data.get(name);
  }

  /** Items in descending priority order; ties keep registration order. */
  values() {
    if (this._sorted === null) {
      const indexed = this._priority.map((entry, index) => ({ ...entry, index }));
      indexed.sort((a, b) => (b.priority - a.priority) || (a.index - b.index));
      this._sorted = indexed.map((entry) => this._data.get(entry.name));
    }
    return this._sorted;
  }

  /** Names in descending priority order. */
  names() {
    const indexed = this._priority.map((entry, index) => ({ ...entry, index }));
    indexed.sort((a, b) => (b.priority - a.priority) || (a.index - b.index));
    return indexed.map((entry) => entry.name);
  }

  [Symbol.iterator]() {
    return this.values()[Symbol.iterator]();
  }
}

/**
 * Does `&` at `pos` open something that already looks like a character
 * reference?  Mirrors `&(?!\#?[xX]?(?:[0-9a-fA-F]+|\w+);)`: the serializer
 * leaves such an `&` alone instead of turning it into `&amp;`.
 *
 * Note the alternation is `[0-9a-fA-F]+` *or* `\w+`, so `&123;` and `&AMP;`
 * both count while `&foo bar;` and `&a-b;` do not.
 */
export function looksLikeEntity(text, pos) {
  let i = pos + 1;
  if (text[i] === '#') i += 1;
  if (text[i] === 'x' || text[i] === 'X') i += 1;
  const bodyStart = i;
  // First alternative: a run of hex digits.
  let j = bodyStart;
  while (j < text.length && isHexDigit(text[j])) j++;
  if (j > bodyStart && text[j] === ';') return true;
  // Second alternative: a run of word characters. Only ASCII word characters
  // can be followed by `;` in practice, but keep the class faithful.
  j = bodyStart;
  while (j < text.length && (isAsciiAlnum(text[j]) || text[j] === '_' || text[j].codePointAt(0) > 127)) j++;
  if (j > bodyStart && text[j] === ';') return true;
  return false;
}

/**
 * Does the text at `pos` match `&(?:\#[0-9]+|\#x[0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);`?
 * Returns the length of the reference, or 0.  This is the stricter class used by
 * the inline entity pattern.
 */
export function entityLength(text, pos) {
  if (text[pos] !== '&') return 0;
  let i = pos + 1;
  if (text[i] === '#') {
    i += 1;
    if (text[i] === 'x') {
      i += 1;
      const start = i;
      while (i < text.length && isHexDigit(text[i])) i++;
      if (i === start) return 0;
    } else {
      const start = i;
      while (i < text.length && isDigit(text[i])) i++;
      if (i === start) return 0;
    }
  } else if (isAsciiLetter(text[i])) {
    i += 1;
    while (i < text.length && isAsciiAlnum(text[i])) i++;
  } else {
    return 0;
  }
  if (text[i] !== ';') return 0;
  return i + 1 - pos;
}

