/**
 * A port of CPython's `html.parser.HTMLParser` tokenizer.
 *
 * Python-Markdown pulls raw HTML out of a document by driving this tokenizer, so
 * its quirks are part of the Markdown output contract — notably:
 *
 *  - `convert_charrefs` is off, so character references are reported separately
 *    instead of being decoded;
 *  - a malformed character reference aborts the scan and the remainder of the
 *    document is reported as one plain-text run;
 *  - `<script>` / `<style>` switch to CDATA mode.
 *
 * Python-Markdown also narrows two of the tokenizer's patterns: entity
 * references must end in a semicolon, and processing instructions must close
 * with `?>`.  Both narrowings are baked in here because that is the only
 * configuration this project ever uses.
 *
 * Subclasses receive absolute source offsets on every callback (`start`), which
 * replaces the line/column bookkeeping the Python version exposes as
 * `line_offset + offset`.
 */

import { isAsciiAlnum, isAsciiLetter, isHexDigit, isDigit, isSpace, startsWith, strip } from './chars.mjs';

/** Characters that terminate a tag name: `[^\t\n\r\f />\x00]`. */
function isTagNameChar(ch) {
  return ch !== undefined && !'\t\n\r\f />\0'.includes(ch);
}

/** `\s` as CPython's `re` module sees it inside tag syntax. */
function isWs(ch) {
  return isSpace(ch);
}

const CDATA_CONTENT_ELEMENTS = new Set(['script', 'style']);

export class HTMLTokenizer {
  constructor() {
    this.source = '';
    this.i = 0;
    this.cdataElem = null;
    this.lasttag = '???';
    this.startTagText = null;
    /** Absolute offset of the construct currently being reported. */
    this.tokenStart = 0;
  }

  reset() {
    this.source = '';
    this.i = 0;
    this.cdataElem = null;
    this.lasttag = '???';
    this.startTagText = null;
    this.tokenStart = 0;
  }

  feed(data) {
    this.source += data;
    this.goahead(false);
  }

  close() {
    this.goahead(true);
  }

  /** Raw source text of the start tag most recently reported. */
  getStarttagText() {
    return this.startTagText;
  }

  // ---- Handlers, overridden by subclasses -------------------------------

  handleStarttag(_tag, _attrs) {}
  handleEndtag(_tag) {}
  handleStartendtag(tag, attrs) {
    this.handleStarttag(tag, attrs);
    this.handleEndtag(tag);
  }
  handleData(_data) {}
  handleComment(_data) {}
  handleDecl(_data) {}
  handlePi(_data) {}
  unknownDecl(_data) {}
  handleCharref(_name) {}
  handleEntityref(_name) {}

  // ---- Scanning helpers -------------------------------------------------

  setCdataMode(elem) {
    this.cdataElem = elem.toLowerCase();
  }

  clearCdataMode() {
    this.cdataElem = null;
  }

  /** Index of the next `</elem` (case-insensitive), or -1. */
  findCdataClose(from) {
    const s = this.source;
    const elem = this.cdataElem;
    for (let k = from; k < s.length; k++) {
      if (s[k] !== '<' || s[k + 1] !== '/') continue;
      let j = k + 2;
      while (j < s.length && isWs(s[j])) j++;
      if (s.slice(j, j + elem.length).toLowerCase() === elem) return k;
    }
    return -1;
  }

  /** Index of the first `<` or `&` at or after `from`, or -1. */
  findInteresting(from) {
    const s = this.source;
    for (let k = from; k < s.length; k++) {
      if (s[k] === '<' || s[k] === '&') return k;
    }
    return -1;
  }

  /**
   * `charref`: `&#(?:[0-9]+|[xX][0-9a-fA-F]+)[^0-9a-fA-F]`.
   * Returns `{ name, end }` or null.  `end` includes the terminating character.
   */
  matchCharref(i) {
    const s = this.source;
    let j = i + 2;
    if (s[j] === 'x' || s[j] === 'X') {
      j += 1;
      const start = j;
      while (j < s.length && isHexDigit(s[j])) j++;
      if (j === start) return null;
    } else {
      const start = j;
      while (j < s.length && isDigit(s[j])) j++;
      if (j === start) return null;
      // A trailing hex letter would extend `[0-9]+`'s terminator class, so the
      // terminator must not itself be a hex digit.
    }
    if (j >= s.length) return null;
    if (isHexDigit(s[j])) return null;
    return { name: s.slice(i + 2, j), end: j + 1 };
  }

  /**
   * `entityref`, as narrowed by Python-Markdown: `&([a-zA-Z][-.a-zA-Z0-9]*);`.
   */
  matchEntityref(i) {
    const s = this.source;
    let j = i + 1;
    if (!isAsciiLetter(s[j])) return null;
    j += 1;
    while (j < s.length && (isAsciiAlnum(s[j]) || s[j] === '-' || s[j] === '.')) j++;
    if (s[j] !== ';') return null;
    return { name: s.slice(i + 1, j), end: j + 1 };
  }

  /** `incomplete`: `&[a-zA-Z#]`. Returns the matched text or null. */
  matchIncomplete(i) {
    const s = this.source;
    const ch = s[i + 1];
    if (ch === '#' || isAsciiLetter(ch)) return s.slice(i, i + 2);
    return null;
  }

  // ---- Main loop --------------------------------------------------------

  goahead(end) {
    const s = this.source;
    const n = s.length;
    let i = this.i;

    while (i < n) {
      let j;
      if (this.cdataElem) {
        j = this.findCdataClose(i);
        if (j < 0) {
          if (!end) break;
          j = n;
        }
      } else {
        j = this.findInteresting(i);
        if (j < 0) j = n;
      }
      if (i < j) {
        this.tokenStart = i;
        this.handleData(s.slice(i, j));
      }
      i = j;
      if (i === n) break;

      if (s[i] === '<') {
        let k;
        if (isAsciiLetter(s[i + 1])) {
          k = this.parseStarttag(i);
        } else if (startsWith(s, '</', i)) {
          k = this.parseEndtag(i);
        } else if (startsWith(s, '<!--', i)) {
          k = this.parseComment(i);
        } else if (startsWith(s, '<?', i)) {
          k = this.parsePi(i);
        } else if (startsWith(s, '<!', i)) {
          k = this.parseHtmlDeclaration(i);
        } else if (i + 1 < n || end) {
          this.tokenStart = i;
          this.handleData('<');
          k = i + 1;
        } else {
          break;
        }
        if (k < 0) {
          if (!end) break;
          k = s.indexOf('>', i + 1);
          if (k < 0) {
            k = s.indexOf('<', i + 1);
            if (k < 0) k = i + 1;
          } else {
            k += 1;
          }
          this.tokenStart = i;
          this.handleData(s.slice(i, k));
        }
        i = k;
      } else if (startsWith(s, '&#', i)) {
        const m = this.matchCharref(i);
        if (m) {
          this.tokenStart = i;
          this.handleCharref(m.name);
          let k = m.end;
          if (s[k - 1] !== ';') k -= 1;
          i = k;
          continue;
        }
        if (s.indexOf(';', i) >= 0) {
          this.tokenStart = i;
          this.handleData(s.slice(i, i + 2));
          i += 2;
        }
        break;
      } else {
        const m = this.matchEntityref(i);
        if (m) {
          this.tokenStart = i;
          this.handleEntityref(m.name);
          let k = m.end;
          if (s[k - 1] !== ';') k -= 1;
          i = k;
          continue;
        }
        const incomplete = this.matchIncomplete(i);
        if (incomplete) {
          // A truncated reference stops the scan; whatever follows is flushed
          // verbatim by the tail handling below.
          if (end && incomplete === s.slice(i)) i += 1;
          break;
        } else if (i + 1 < n) {
          this.tokenStart = i;
          this.handleData('&');
          i += 1;
        } else {
          break;
        }
      }
    }

    if (end && i < n) {
      this.tokenStart = i;
      this.handleData(s.slice(i, n));
      i = n;
    }
    this.i = i;
  }

  // ---- Individual constructs -------------------------------------------

  /**
   * `locatestarttagend_tolerant` followed by `check_for_whole_start_tag`.
   * Returns the offset just past the tag, or -1 when the tag is truncated.
   */
  checkForWholeStartTag(i) {
    const s = this.source;
    let j = i + 1;
    while (isTagNameChar(s[j])) j++;

    // Attribute list: `(?:[\s/]* (attr)* )? \s*`
    for (;;) {
      const attrStart = j;
      while (j < s.length && (isWs(s[j]) || (s[j] === '/' && s[j + 1] !== '>'))) j++;
      // An attribute name must be preceded by a quote, whitespace or a slash.
      const prev = s[j - 1];
      const separated = j > attrStart || prev === '"' || prev === "'";
      if (!separated) break;
      if (j >= s.length) break;
      if (s[j] === '>' || s[j] === '/' || isWs(s[j])) break;
      // name: `[^\s/>][^\s/=>]*`
      j += 1;
      while (j < s.length && !isWs(s[j]) && s[j] !== '/' && s[j] !== '=' && s[j] !== '>') j++;
      // optional `\s*=+\s*` value
      let k = j;
      while (k < s.length && isWs(s[k])) k++;
      if (s[k] === '=') {
        while (s[k] === '=') k++;
        while (k < s.length && isWs(s[k])) k++;
        if (s[k] === "'" || s[k] === '"') {
          const quote = s[k];
          const close = s.indexOf(quote, k + 1);
          if (close < 0) {
            // Unterminated quoted value: the tag cannot be completed here.
            j = k;
          } else {
            j = close + 1;
          }
        } else {
          while (k < s.length && !isWs(s[k]) && s[k] !== '>') k++;
          j = k;
        }
        // `(?:\s*,)*`
        for (;;) {
          let c = j;
          while (c < s.length && isWs(s[c])) c++;
          if (s[c] === ',') j = c + 1;
          else break;
        }
      }
      // `(?:\s|/(?!>))*`
      while (j < s.length && (isWs(s[j]) || (s[j] === '/' && s[j + 1] !== '>'))) j++;
    }
    while (j < s.length && isWs(s[j])) j++;

    const next = s[j] ?? '';
    if (next === '>') return j + 1;
    if (next === '/') {
      if (startsWith(s, '/>', j)) return j + 2;
      return -1;
    }
    if (next === '') return -1;
    if (isAsciiLetter(next) || next === '=' || next === '/') return -1;
    return j > i ? j : i + 1;
  }

  parseStarttag(i) {
    const s = this.source;
    this.startTagText = null;
    const endpos = this.checkForWholeStartTag(i);
    if (endpos < 0) return endpos;
    this.startTagText = s.slice(i, endpos);

    // Tag name.
    let k = i + 1;
    while (isTagNameChar(s[k])) k++;
    const tag = s.slice(i + 1, k).toLowerCase();
    this.lasttag = tag;
    while (k < endpos && (isWs(s[k]) || (s[k] === '/' && s[k + 1] !== '>'))) k++;

    const attrs = [];
    while (k < endpos) {
      if (s[k] === '>' || s[k] === '/') break;
      const nameStart = k;
      k += 1;
      while (k < endpos && !isWs(s[k]) && s[k] !== '/' && s[k] !== '=' && s[k] !== '>') k++;
      const name = s.slice(nameStart, k).toLowerCase();
      let value = null;
      let probe = k;
      while (probe < endpos && isWs(s[probe])) probe++;
      if (s[probe] === '=') {
        while (s[probe] === '=') probe++;
        while (probe < endpos && isWs(s[probe])) probe++;
        if (s[probe] === "'" || s[probe] === '"') {
          const quote = s[probe];
          const close = s.indexOf(quote, probe + 1);
          if (close >= 0 && close < endpos) {
