    if (tail.endsWith('/>')) {
      this.handleStartendtag(tag, attrs);
    } else {
      this.handleStarttag(tag, attrs);
      if (CDATA_CONTENT_ELEMENTS.has(tag)) this.setCdataMode(tag);
    }
    return endpos;
  }

  parseEndtag(i) {
    const s = this.source;
    const gt = s.indexOf('>', i + 1);
    if (gt < 0) return -1;
    let gtpos = gt + 1;

    // `endtagfind`: `</\s*([a-zA-Z][-.a-zA-Z0-9:_]*)\s*>`
    let j = i + 2;
    while (j < s.length && isWs(s[j])) j++;
    const nameStart = j;
    let wellFormed = false;
    let elem = '';
    if (isAsciiLetter(s[j])) {
      j += 1;
      while (j < s.length && (isAsciiAlnum(s[j]) || '-.:_'.includes(s[j]))) j++;
      elem = s.slice(nameStart, j).toLowerCase();
      let t = j;
      while (t < s.length && isWs(s[t])) t++;
      if (s[t] === '>') {
        wellFormed = true;
        gtpos = t + 1;
      }
    }

    if (!wellFormed) {
      if (this.cdataElem !== null) {
        this.tokenStart = i;
        this.handleData(s.slice(i, gtpos));
        return gtpos;
      }
      // Recover the tag name and skip whatever follows it up to `>`.
      let m = i + 2;
      if (!isAsciiLetter(s[m])) {
        if (startsWith(s, '</>', i)) return i + 3;
        return this.parseBogusComment(i);
      }
      const start = m;
      while (isTagNameChar(s[m])) m++;
      const tagname = s.slice(start, m).toLowerCase();
      const close = s.indexOf('>', m);
      this.tokenStart = i;
      this.handleEndtag(tagname);
      return close + 1;
    }

    if (this.cdataElem !== null && elem !== this.cdataElem) {
      this.tokenStart = i;
      this.handleData(s.slice(i, gtpos));
      return gtpos;
    }

    this.tokenStart = i;
    this.handleEndtag(elem);
    this.clearCdataMode();
    return gtpos;
  }

  parseComment(i) {
    const s = this.source;
    // `_commentclose`: `--\s*>`
    let search = i + 4;
    for (;;) {
      const dash = s.indexOf('--', search);
      if (dash < 0) return -1;
      let k = dash + 2;
      while (k < s.length && isWs(s[k])) k++;
      if (s[k] === '>') {
        this.tokenStart = i;
        this.handleComment(s.slice(i + 4, dash));
        return k + 1;
      }
      search = dash + 1;
    }
  }

  parsePi(i) {
    const s = this.source;
    // Python-Markdown narrows `piclose` to `\?>`.
    const close = s.indexOf('?>', i + 2);
    if (close < 0) return -1;
    this.tokenStart = i;
    this.handlePi(s.slice(i + 2, close));
    return close + 2;
  }

  parseHtmlDeclaration(i) {
    const s = this.source;
    if (startsWith(s, '<!--', i)) return this.parseComment(i);
    if (startsWith(s, '<![', i)) return this.parseMarkedSection(i);
    if (s.slice(i, i + 9).toLowerCase() === '<!doctype') {
      const gt = s.indexOf('>', i + 9);
      if (gt < 0) return -1;
      this.tokenStart = i;
      this.handleDecl(s.slice(i + 2, gt));
      return gt + 1;
    }
    return this.parseBogusComment(i);
  }

  parseMarkedSection(i) {
    const s = this.source;
    let j = i + 3;
    if (!isAsciiLetter(s[j])) return -1;
    const start = j;
    j += 1;
    while (j < s.length && (isAsciiAlnum(s[j]) || '-_.'.includes(s[j]))) j++;
    const sectName = s.slice(start, j).toLowerCase();

    let closeStart = -1;
    let closeEnd = -1;
    if (['temp', 'cdata', 'ignore', 'include', 'rcdata'].includes(sectName)) {
      // `]\s*]\s*>`
      const found = this.findBracketClose(i + 3, 2);
      if (found) { closeStart = found.start; closeEnd = found.end; }
    } else if (['if', 'else', 'endif'].includes(sectName)) {
      const found = this.findBracketClose(i + 3, 1);
      if (found) { closeStart = found.start; closeEnd = found.end; }
    } else {
      return -1;
    }
    if (closeStart < 0) return -1;
    this.tokenStart = i;
    this.unknownDecl(s.slice(i + 3, closeStart));
    return closeEnd;
  }

  /** Locate `]` repeated `count` times (whitespace allowed between) then `>`. */
  findBracketClose(from, count) {
    const s = this.source;
    for (let k = from; k < s.length; k++) {
      if (s[k] !== ']') continue;
      let j = k;
      let matched = 0;
      while (matched < count) {
        if (s[j] !== ']') break;
        matched += 1;
        j += 1;
        while (j < s.length && isWs(s[j])) j++;
      }
      if (matched === count && s[j] === '>') return { start: k, end: j + 1 };
    }
    return null;
  }

  /**
   * Bogus comment (`<!foo>`, `</3>`).  Python-Markdown suppresses the usual
   * `handle_comment` report and passes the source through untouched instead.
   */
  parseBogusComment(i) {
    const s = this.source;
    const pos = s.indexOf('>', i + 2);
    if (pos === -1) return -1;
    this.tokenStart = i;
    this.handleBogusComment(s.slice(i, pos + 1));
    return pos + 1;
  }

  handleBogusComment(_text) {}
}

/**
 * `html.unescape` restricted to what start-tag attribute values need. Attribute
 * values are the only place the tokenizer decodes references.
 */
function unescapeCharrefs(value) {
  if (!value.includes('&')) return value;
  let out = '';
  let i = 0;
  while (i < value.length) {
    if (value[i] !== '&') { out += value[i]; i += 1; continue; }
    if (value[i + 1] === '#') {
      let j = i + 2;
      let code = null;
      if (value[j] === 'x' || value[j] === 'X') {
        const start = j + 1;
        j += 1;
        while (j < value.length && isHexDigit(value[j])) j++;
        if (j > start) code = parseInt(value.slice(start, j), 16);
      } else {
        const start = j;
        while (j < value.length && isDigit(value[j])) j++;
        if (j > start) code = parseInt(value.slice(start, j), 10);
      }
      if (code !== null) {
        if (value[j] === ';') j += 1;
        out += safeFromCodePoint(code);
        i = j;
        continue;
      }
    } else {
      let j = i + 1;
      while (j < value.length && isAsciiAlnum(value[j])) j++;
      const name = value.slice(i + 1, j);
      const semi = value[j] === ';';
      const replacement = NAMED_REFS.get(name);
      if (replacement !== undefined) {
        out += replacement;
        i = semi ? j + 1 : j;
        continue;
      }
    }
    out += '&';
    i += 1;
  }
  return out;
}

function safeFromCodePoint(code) {
  if (code < 0 || code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) return '�';
  return String.fromCodePoint(code);
}

/** The handful of named references that realistically appear in attributes. */
const NAMED_REFS = new Map(Object.entries({
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  copy: '©', reg: '®', trade: '™', hellip: '…',
  mdash: '—', ndash: '–', lsquo: '‘', rsquo: '’',
  ldquo: '“', rdquo: '”',
}));

export { CDATA_CONTENT_ELEMENTS };

