/**
 * A port of CPython's `html.parser.HTMLParser` tokenizer.
 *
 * Python-Markdown pulls raw HTML out of a document by driving this tokenizer, so
 * its quirks are part of the Markdown output contract — notably:
 *
 *  - `convert_charrefs` is off, so character references are reported separately
 *    instead of being decoded;
 *  - a malformed character reference aborts the scan and the remainder of the
 *    document is reported as one plain-text run;
 *  - `<script>` / `<style>` switch to CDATA mode.
 *
 * Python-Markdown also narrows two of the tokenizer's patterns: entity
 * references must end in a semicolon, and processing instructions must close
 * with `?>`.  Both narrowings are baked in here because that is the only
 * configuration this project ever uses.
 *
 * Subclasses receive absolute source offsets on every callback (`start`), which
 * replaces the line/column bookkeeping the Python version exposes as
 * `line_offset + offset`.
 */

import { isAsciiAlnum, isAsciiLetter, isHexDigit, isDigit, isSpace, startsWith, strip } from './chars.mjs';

/** Characters that terminate a tag name: `[^\t\n\r\f />\x00]`. */
function isTagNameChar(ch) {
  return ch !== undefined && !'\t\n\r\f />\0'.includes(ch);
}

/** `\s` as CPython's `re` module sees it inside tag syntax. */
function isWs(ch) {
  return isSpace(ch);
}

const CDATA_CONTENT_ELEMENTS = new Set(['script', 'style']);

export class HTMLTokenizer {
  constructor() {
    this.source = '';
    this.i = 0;
    this.cdataElem = null;
    this.lasttag = '???';
    this.startTagText = null;
    /** Absolute offset of the construct currently being reported. */
    this.tokenStart = 0;
  }

  reset() {
    this.source = '';
    this.i = 0;
    this.cdataElem = null;
    this.lasttag = '???';
    this.startTagText = null;
    this.tokenStart = 0;
  }

  feed(data) {
    this.source += data;
    this.goahead(false);
  }

  close() {
    this.goahead(true);
  }

  /** Raw source text of the start tag most recently reported. */
  getStarttagText() {
    return this.startTagText;
  }

  // ---- Handlers, overridden by subclasses -------------------------------

  handleStarttag(_tag, _attrs) {}
  handleEndtag(_tag) {}
  handleStartendtag(tag, attrs) {
    this.handleStarttag(tag, attrs);
    this.handleEndtag(tag);
  }
  handleData(_data) {}
  handleComment(_data) {}
  handleDecl(_data) {}
  handlePi(_data) {}
  unknownDecl(_data) {}
  handleCharref(_name) {}
  handleEntityref(_name) {}

  // ---- Scanning helpers -------------------------------------------------

  setCdataMode(elem) {
    this.cdataElem = elem.toLowerCase();
  }

  clearCdataMode() {
    this.cdataElem = null;
  }

  /** Index of the next `</elem` (case-insensitive), or -1. */
  findCdataClose(from) {
    const s = this.source;
    const elem = this.cdataElem;
    for (let k = from; k < s.length; k++) {
      if (s[k] !== '<' || s[k + 1] !== '/') continue;
      let j = k + 2;
      while (j < s.length && isWs(s[j])) j++;
      if (s.slice(j, j + elem.length).toLowerCase() === elem) return k;
    }
    return -1;
  }

  /** Index of the first `<` or `&` at or after `from`, or -1. */
  findInteresting(from) {
    const s = this.source;
    for (let k = from; k < s.length; k++) {
      if (s[k] === '<' || s[k] === '&') return k;
    }
    return -1;
  }

  /**
   * `charref`: `&#(?:[0-9]+|[xX][0-9a-fA-F]+)[^0-9a-fA-F]`.
   * Returns `{ name, end }` or null.  `end` includes the terminating character.
   */
  matchCharref(i) {
    const s = this.source;
    let j = i + 2;
    if (s[j] === 'x' || s[j] === 'X') {
      j += 1;
      const start = j;
      while (j < s.length && isHexDigit(s[j])) j++;
      if (j === start) return null;
    } else {
      const start = j;
      while (j < s.length && isDigit(s[j])) j++;
      if (j === start) return null;
      // A trailing hex letter would extend `[0-9]+`'s terminator class, so the
      // terminator must not itself be a hex digit.
    }
    if (j >= s.length) return null;
    if (isHexDigit(s[j])) return null;
    return { name: s.slice(i + 2, j), end: j + 1 };
  }

  /**
   * `entityref`, as narrowed by Python-Markdown: `&([a-zA-Z][-.a-zA-Z0-9]*);`.
   */
  matchEntityref(i) {
    const s = this.source;
    let j = i + 1;
    if (!isAsciiLetter(s[j])) return null;
    j += 1;
    while (j < s.length && (isAsciiAlnum(s[j]) || s[j] === '-' || s[j] === '.')) j++;
    if (s[j] !== ';') return null;
    return { name: s.slice(i + 1, j), end: j + 1 };
  }

  /** `incomplete`: `&[a-zA-Z#]`. Returns the matched text or null. */
  matchIncomplete(i) {
    const s = this.source;
    const ch = s[i + 1];
    if (ch === '#' || isAsciiLetter(ch)) return s.slice(i, i + 2);
    return null;
  }

  // ---- Main loop --------------------------------------------------------

  goahead(end) {
    const s = this.source;
    const n = s.length;
    let i = this.i;

    while (i < n) {
      let j;
      if (this.cdataElem) {
        j = this.findCdataClose(i);
        if (j < 0) {
          if (!end) break;
          j = n;
        }
      } else {
        j = this.findInteresting(i);
        if (j < 0) j = n;
      }
      if (i < j) {
        this.tokenStart = i;
        this.handleData(s.slice(i, j));
      }
      i = j;
      if (i === n) break;

      if (s[i] === '<') {
        let k;
        if (isAsciiLetter(s[i + 1])) {
          k = this.parseStarttag(i);
        } else if (startsWith(s, '</', i)) {
          k = this.parseEndtag(i);
        } else if (startsWith(s, '<!--', i)) {
          k = this.parseComment(i);
        } else if (startsWith(s, '<?', i)) {
          k = this.parsePi(i);
        } else if (startsWith(s, '<!', i)) {
          k = this.parseHtmlDeclaration(i);
        } else if (i + 1 < n || end) {
          this.tokenStart = i;
          this.handleData('<');
          k = i + 1;
        } else {
          break;
        }
        if (k < 0) {
          if (!end) break;
          k = s.indexOf('>', i + 1);
          if (k < 0) {
            k = s.indexOf('<', i + 1);
            if (k < 0) k = i + 1;
          } else {
            k += 1;
          }
          this.tokenStart = i;
          this.handleData(s.slice(i, k));
        }
        i = k;
      } else if (startsWith(s, '&#', i)) {
        const m = this.matchCharref(i);
        if (m) {
          this.tokenStart = i;
          this.handleCharref(m.name);
          let k = m.end;
          if (s[k - 1] !== ';') k -= 1;
          i = k;
          continue;
        }
        if (s.indexOf(';', i) >= 0) {
          this.tokenStart = i;
          this.handleData(s.slice(i, i + 2));
          i += 2;
        }
        break;
      } else {
        const m = this.matchEntityref(i);
        if (m) {
          this.tokenStart = i;
          this.handleEntityref(m.name);
          let k = m.end;
          if (s[k - 1] !== ';') k -= 1;
          i = k;
          continue;
        }
        const incomplete = this.matchIncomplete(i);
        if (incomplete) {
          // A truncated reference stops the scan; whatever follows is flushed
          // verbatim by the tail handling below.
          if (end && incomplete === s.slice(i)) i += 1;
          break;
        } else if (i + 1 < n) {
          this.tokenStart = i;
          this.handleData('&');
          i += 1;
        } else {
          break;
        }
      }
    }

    if (end && i < n) {
      this.tokenStart = i;
      this.handleData(s.slice(i, n));
      i = n;
    }
    this.i = i;
  }

  // ---- Individual constructs -------------------------------------------

  /**
   * `locatestarttagend_tolerant` followed by `check_for_whole_start_tag`.
   * Returns the offset just past the tag, or -1 when the tag is truncated.
   */
  checkForWholeStartTag(i) {
    const s = this.source;
    let j = i + 1;
    while (isTagNameChar(s[j])) j++;

    // Attribute list: `(?:[\s/]* (attr)* )? \s*`
    for (;;) {
      const attrStart = j;
      while (j < s.length && (isWs(s[j]) || (s[j] === '/' && s[j + 1] !== '>'))) j++;
      // An attribute name must be preceded by a quote, whitespace or a slash.
      const prev = s[j - 1];
      const separated = j > attrStart || prev === '"' || prev === "'";
      if (!separated) break;
      if (j >= s.length) break;
      if (s[j] === '>' || s[j] === '/' || isWs(s[j])) break;
      // name: `[^\s/>][^\s/=>]*`
      j += 1;
      while (j < s.length && !isWs(s[j]) && s[j] !== '/' && s[j] !== '=' && s[j] !== '>') j++;
      // optional `\s*=+\s*` value
      let k = j;
      while (k < s.length && isWs(s[k])) k++;
      if (s[k] === '=') {
        while (s[k] === '=') k++;
        while (k < s.length && isWs(s[k])) k++;
        if (s[k] === "'" || s[k] === '"') {
          const quote = s[k];
          const close = s.indexOf(quote, k + 1);
          if (close < 0) {
            // Unterminated quoted value: the tag cannot be completed here.
            j = k;
          } else {
            j = close + 1;
          }
        } else {
          while (k < s.length && !isWs(s[k]) && s[k] !== '>') k++;
          j = k;
        }
        // `(?:\s*,)*`
        for (;;) {
          let c = j;
          while (c < s.length && isWs(s[c])) c++;
          if (s[c] === ',') j = c + 1;
          else break;
        }
      }
      // `(?:\s|/(?!>))*`
      while (j < s.length && (isWs(s[j]) || (s[j] === '/' && s[j + 1] !== '>'))) j++;
    }
    while (j < s.length && isWs(s[j])) j++;

    const next = s[j] ?? '';
    if (next === '>') return j + 1;
    if (next === '/') {
      if (startsWith(s, '/>', j)) return j + 2;
      return -1;
    }
    if (next === '') return -1;
    if (isAsciiLetter(next) || next === '=' || next === '/') return -1;
    return j > i ? j : i + 1;
  }

  parseStarttag(i) {
    const s = this.source;
    this.startTagText = null;
    const endpos = this.checkForWholeStartTag(i);
    if (endpos < 0) return endpos;
    this.startTagText = s.slice(i, endpos);

    // Tag name.
    let k = i + 1;
    while (isTagNameChar(s[k])) k++;
    const tag = s.slice(i + 1, k).toLowerCase();
    this.lasttag = tag;
    while (k < endpos && (isWs(s[k]) || (s[k] === '/' && s[k + 1] !== '>'))) k++;

    const attrs = [];
    while (k < endpos) {
      if (s[k] === '>' || s[k] === '/') break;
      const nameStart = k;
      k += 1;
      while (k < endpos && !isWs(s[k]) && s[k] !== '/' && s[k] !== '=' && s[k] !== '>') k++;
      const name = s.slice(nameStart, k).toLowerCase();
      let value = null;
      let probe = k;
      while (probe < endpos && isWs(s[probe])) probe++;
      if (s[probe] === '=') {
        while (s[probe] === '=') probe++;
        while (probe < endpos && isWs(s[probe])) probe++;
        if (s[probe] === "'" || s[probe] === '"') {
          const quote = s[probe];
          const close = s.indexOf(quote, probe + 1);
          if (close >= 0 && close < endpos) {
            value = s.slice(probe + 1, close);
            k = close + 1;
          } else {
            value = s.slice(probe + 1, endpos);
            k = endpos;
          }
        } else {
          const valueStart = probe;
          while (probe < endpos && !isWs(s[probe]) && s[probe] !== '>') probe++;
          value = s.slice(valueStart, probe);
          k = probe;
        }
        if (value) value = unescapeCharrefs(value);
      }
      attrs.push([name, value]);
      while (k < endpos && (isWs(s[k]) || (s[k] === '/' && s[k + 1] !== '>'))) k++;
    }

    const tail = strip(s.slice(k, endpos));
    if (tail !== '>' && tail !== '/>') {
      this.tokenStart = i;
      this.handleData(s.slice(i, endpos));
      return endpos;
    }
    this.tokenStart = i;
    if (tail.endsWith('/>')) {
      this.handleStartendtag(tag, attrs);
    } else {
      this.handleStarttag(tag, attrs);
      if (CDATA_CONTENT_ELEMENTS.has(tag)) this.setCdataMode(tag);
    }
    return endpos;
  }

  parseEndtag(i) {
    const s = this.source;
    const gt = s.indexOf('>', i + 1);
    if (gt < 0) return -1;
    let gtpos = gt + 1;

    // `endtagfind`: `</\s*([a-zA-Z][-.a-zA-Z0-9:_]*)\s*>`
    let j = i + 2;
    while (j < s.length && isWs(s[j])) j++;
    const nameStart = j;
    let wellFormed = false;
    let elem = '';
    if (isAsciiLetter(s[j])) {
      j += 1;
      while (j < s.length && (isAsciiAlnum(s[j]) || '-.:_'.includes(s[j]))) j++;
      elem = s.slice(nameStart, j).toLowerCase();
      let t = j;
      while (t < s.length && isWs(s[t])) t++;
      if (s[t] === '>') {
        wellFormed = true;
        gtpos = t + 1;
      }
    }

    if (!wellFormed) {
      if (this.cdataElem !== null) {
        this.tokenStart = i;
        this.handleData(s.slice(i, gtpos));
        return gtpos;
      }
      // Recover the tag name and skip whatever follows it up to `>`.
      let m = i + 2;
      if (!isAsciiLetter(s[m])) {
        if (startsWith(s, '</>', i)) return i + 3;
        return this.parseBogusComment(i);
      }
      const start = m;
      while (isTagNameChar(s[m])) m++;
      const tagname = s.slice(start, m).toLowerCase();
      const close = s.indexOf('>', m);
      this.tokenStart = i;
      this.handleEndtag(tagname);
      return close + 1;
    }

    if (this.cdataElem !== null && elem !== this.cdataElem) {
      this.tokenStart = i;
      this.handleData(s.slice(i, gtpos));
      return gtpos;
    }

    this.tokenStart = i;
    this.handleEndtag(elem);
    this.clearCdataMode();
    return gtpos;
  }

  parseComment(i) {
    const s = this.source;
    // `_commentclose`: `--\s*>`
    let search = i + 4;
    for (;;) {
      const dash = s.indexOf('--', search);
      if (dash < 0) return -1;
      let k = dash + 2;
      while (k < s.length && isWs(s[k])) k++;
      if (s[k] === '>') {
        this.tokenStart = i;
        this.handleComment(s.slice(i + 4, dash));
        return k + 1;
      }
      search = dash + 1;
    }
  }

  parsePi(i) {
    const s = this.source;
    // Python-Markdown narrows `piclose` to `\?>`.
    const close = s.indexOf('?>', i + 2);
    if (close < 0) return -1;
    this.tokenStart = i;
    this.handlePi(s.slice(i + 2, close));
    return close + 2;
  }

  parseHtmlDeclaration(i) {
    const s = this.source;
    if (startsWith(s, '<!--', i)) return this.parseComment(i);
    if (startsWith(s, '<![', i)) return this.parseMarkedSection(i);
    if (s.slice(i, i + 9).toLowerCase() === '<!doctype') {
      const gt = s.indexOf('>', i + 9);
      if (gt < 0) return -1;
      this.tokenStart = i;
      this.handleDecl(s.slice(i + 2, gt));
      return gt + 1;
    }
    return this.parseBogusComment(i);
  }

  parseMarkedSection(i) {
    const s = this.source;
    let j = i + 3;
    if (!isAsciiLetter(s[j])) return -1;
    const start = j;
    j += 1;
    while (j < s.length && (isAsciiAlnum(s[j]) || '-_.'.includes(s[j]))) j++;
    const sectName = s.slice(start, j).toLowerCase();

    let closeStart = -1;
    let closeEnd = -1;
    if (['temp', 'cdata', 'ignore', 'include', 'rcdata'].includes(sectName)) {
      // `]\s*]\s*>`
      const found = this.findBracketClose(i + 3, 2);
      if (found) { closeStart = found.start; closeEnd = found.end; }
    } else if (['if', 'else', 'endif'].includes(sectName)) {
      const found = this.findBracketClose(i + 3, 1);
      if (found) { closeStart = found.start; closeEnd = found.end; }
    } else {
      return -1;
    }
    if (closeStart < 0) return -1;
    this.tokenStart = i;
    this.unknownDecl(s.slice(i + 3, closeStart));
    return closeEnd;
  }

  /** Locate `]` repeated `count` times (whitespace allowed between) then `>`. */
  findBracketClose(from, count) {
    const s = this.source;
    for (let k = from; k < s.length; k++) {
      if (s[k] !== ']') continue;
      let j = k;
      let matched = 0;
      while (matched < count) {
        if (s[j] !== ']') break;
        matched += 1;
        j += 1;
        while (j < s.length && isWs(s[j])) j++;
      }
      if (matched === count && s[j] === '>') return { start: k, end: j + 1 };
    }
    return null;
  }

  /**
   * Bogus comment (`<!foo>`, `</3>`).  Python-Markdown suppresses the usual
   * `handle_comment` report and passes the source through untouched instead.
   */
  parseBogusComment(i) {
    const s = this.source;
    const pos = s.indexOf('>', i + 2);
    if (pos === -1) return -1;
    this.tokenStart = i;
    this.handleBogusComment(s.slice(i, pos + 1));
    return pos + 1;
  }

  handleBogusComment(_text) {}
}

/**
 * `html.unescape` restricted to what start-tag attribute values need. Attribute
 * values are the only place the tokenizer decodes references.
 */
function unescapeCharrefs(value) {
  if (!value.includes('&')) return value;
  let out = '';
  let i = 0;
  while (i < value.length) {
    if (value[i] !== '&') { out += value[i]; i += 1; continue; }
    if (value[i + 1] === '#') {
      let j = i + 2;
      let code = null;
      if (value[j] === 'x' || value[j] === 'X') {
        const start = j + 1;
        j += 1;
        while (j < value.length && isHexDigit(value[j])) j++;
        if (j > start) code = parseInt(value.slice(start, j), 16);
      } else {
        const start = j;
        while (j < value.length && isDigit(value[j])) j++;
        if (j > start) code = parseInt(value.slice(start, j), 10);
      }
      if (code !== null) {
        if (value[j] === ';') j += 1;
        out += safeFromCodePoint(code);
        i = j;
        continue;
      }
    } else {
      let j = i + 1;
      while (j < value.length && isAsciiAlnum(value[j])) j++;
      const name = value.slice(i + 1, j);
      const semi = value[j] === ';';
      const replacement = NAMED_REFS.get(name);
      if (replacement !== undefined) {
        out += replacement;
        i = semi ? j + 1 : j;
        continue;
      }
    }
    out += '&';
    i += 1;
  }
  return out;
}

function safeFromCodePoint(code) {
  if (code < 0 || code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) return '�';
  return String.fromCodePoint(code);
}

/** The handful of named references that realistically appear in attributes. */
const NAMED_REFS = new Map(Object.entries({
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  copy: '©', reg: '®', trade: '™', hellip: '…',
  mdash: '—', ndash: '–', lsquo: '‘', rsquo: '’',
  ldquo: '“', rdquo: '”',
}));

export { CDATA_CONTENT_ELEMENTS };

