/**
 * Raw-HTML extraction.
 *
 * Drives the tokenizer over the whole document and rewrites it into a "clean"
 * document where every span of raw HTML has been replaced by an `HtmlStash`
 * placeholder.  The blank lines this inserts around each placeholder are what
 * later cause the block parser to treat the raw HTML as its own block, so the
 * exact newline bookkeeping below is observable in the final output.
 */

import { HTMLTokenizer } from './htmlparser.mjs';
import { strip } from './chars.mjs';

/**
 * `blank_line_re`: `^([ ]*\n){2}` — two consecutive lines that hold nothing but
 * spaces.  Used to decide whether a raw block is followed by a blank line (in
 * which case the blank line is folded into the stashed HTML) or by more content
 * on the next line (which puts the extractor into "tail" mode).
 */
function matchesBlankLines(text, pos) {
  let i = pos;
  for (let repeat = 0; repeat < 2; repeat++) {
    while (text[i] === ' ') i++;
    if (text[i] !== '\n') return false;
    i += 1;
  }
  return true;
}

export class HTMLExtractor extends HTMLTokenizer {
  constructor(md) {
    super();
    this.md = md;
    this.emptyTags = new Set(md.emptyTags);
    this.inraw = false;
    this.intail = false;
    this.stack = [];
    this._cache = [];
    this.cleandoc = [];
  }

  reset() {
    super.reset();
    this.inraw = false;
    this.intail = false;
    this.stack = [];
    this._cache = [];
    this.cleandoc = [];
  }

  close() {
    super.close();
    if (this._cache.length) {
      this.cleandoc.push(this.md.htmlStash.store(this._cache.join('')));
      this._cache = [];
    }
  }

  /**
   * Is the current construct at the start of a line?  Up to four leading
   * whitespace characters still count, matching the reference implementation.
   */
  atLineStart() {
    const lineStart = this.source.lastIndexOf('\n', this.tokenStart - 1) + 1;
    const offset = this.tokenStart - lineStart;
    if (offset === 0) return true;
    if (offset > 4) return false;
    return strip(this.source.slice(lineStart, this.tokenStart)) === '';
  }

  /** Raw source text of the end tag currently being reported. */
  getEndtagText(tag) {
    const gt = this.source.indexOf('>', this.tokenStart);
    if (gt >= 0) return this.source.slice(this.tokenStart, gt + 1);
    return `</${tag}>`;
  }

  handleStarttag(tag, attrs) {
    // Tags that never close would otherwise leave the raw stack unbalanced.
    if (this.emptyTags.has(tag)) {
      this.handleStartendtag(tag, attrs);
      return;
    }

    if (this.md.isBlockLevel(tag) && (this.intail || (this.atLineStart() && !this.inraw))) {
      this.inraw = true;
      this.cleandoc.push('\n');
    }

    const text = this.getStarttagText();
    if (this.inraw) {
      this.stack.push(tag);
      this._cache.push(text);
    } else {
      this.cleandoc.push(text);
    }
  }

  handleEndtag(tag) {
    const text = this.getEndtagText(tag);

    if (this.inraw) {
      this._cache.push(text);
      if (this.stack.includes(tag)) {
        while (this.stack.length) {
          if (this.stack.pop() === tag) break;
        }
      }
      if (this.stack.length === 0) {
        if (matchesBlankLines(this.source, this.tokenStart + text.length)) {
          // Fold the blank line into the raw block.
          this._cache.push('\n');
        } else {
          // Content follows on the same or next line.
          this.intail = true;
        }
        this.inraw = false;
        this.cleandoc.push(this.md.htmlStash.store(this._cache.join('')));
        this.cleandoc.push('\n\n');
        this._cache = [];
      }
    } else {
      this.cleandoc.push(text);
    }
  }

  handleData(data) {
    if (this.intail && data.includes('\n')) this.intail = false;
    if (this.inraw) this._cache.push(data);
    else this.cleandoc.push(data);
  }

  /** A construct with no closing tag: `<hr>`, `<br />`, a comment, a doctype... */
  handleEmptyTag(data, isBlock) {
    if (this.inraw || this.intail) {
      this._cache.push(data);
      return;
    }
    if (this.atLineStart() && isBlock) {
      let text = data;
      if (matchesBlankLines(this.source, this.tokenStart + data.length)) {
        text += '\n';
      } else {
        this.intail = true;
      }
      const previous = this.cleandoc.length ? this.cleandoc[this.cleandoc.length - 1] : '';
      // Guarantee a blank line before the block, not just a line break.
      if (!previous.endsWith('\n\n') && previous.endsWith('\n')) this.cleandoc.push('\n');
      this.cleandoc.push(this.md.htmlStash.store(text));
      this.cleandoc.push('\n\n');
    } else {
      this.cleandoc.push(this.md.htmlStash.store(data));
    }
  }

  handleStartendtag(tag, _attrs) {
    this.handleEmptyTag(this.getStarttagText(), this.md.isBlockLevel(tag));
  }

  handleCharref(name) {
    this.handleData(`&#${name};`);
  }

  handleEntityref(name) {
    this.handleData(`&${name};`);
  }

  handleComment(data) {
    this.handleEmptyTag(`<!--${data}-->`, true);
  }

  handleDecl(data) {
    this.handleEmptyTag(`<!${data}>`, true);
  }

  handlePi(data) {
    this.handleEmptyTag(`<?${data}?>`, true);
  }

  unknownDecl(data) {
    const end = data.startsWith('CDATA[') ? ']]>' : ']>';
    this.handleEmptyTag(`<![${data}${end}`, true);
  }

  handleBogusComment(text) {
    this.handleEmptyTag(text, false);
  }
}

